from taf.selenium.mobile.gnb.oam.coam.classical.pages.navigator import Menu


class MenuList(object):
    def __init__(self, tool):
        self._tool = tool

    @property
    def site_view_page(self):
        return Menu(self._tool, ['BTS Status', 'Site View'])

    @property
    def software_management_page(self):
        return Menu(self._tool, ['Software Management'])
